            m = re.match(r"^/orders/([^/]+)/(confirm|pay)$", self.path)
            if m:
                order_id, action = m.group(1), m.group(2)
                try:
                    if action == "confirm":
                        order = service.confirm(order_id)
                    else:
                        order = service.pay(order_id, day_provider())
                except KeyError:
                    return self._send(404, {"error": "no such order"})
                except Exception as exc:  # noqa: BLE001 - bad transition -> 409
                    return self._send(409, {"error": str(exc)})
                return self._send(200, order.to_dict())
            if self.path != "/orders":
                return self._send(404, {"error": "not found"})"""
assert src.count(old) == 1, "do_POST anchor"
